with filtered as (select *, dayofweek(start_date) as start_date_dayofweek from subscriptions where end_date > date '2023-08-20') select id, plan, end_date, status, dense_rank() over (partition by status, plan order by monthly_fee desc nulls first) as monthly_fee_dense_rank, first_value(start_date_dayofweek) ignore nulls over (partition by status order by start_date_dayofweek, id rows between unbounded preceding and current row) as first_known_start_date_dayofweek, last_value(monthly_fee) ignore nulls over (order by end_date, id rows between unbounded preceding and current row) as last_known_monthly_fee, stddev_samp(monthly_fee) over (partition by customer_id) as customer_id_stddev_samp_monthly_fee, ntile(3) over (order by monthly_fee desc, id) as monthly_fee_bucket from filtered;
